    {"claim": "Nothing in a training run lets an auditor reach in and regenerate the join graph.", "targets": ["AN-31"]},
    {"claim": "It proves nobody altered the record after it was written. That's integrity. It says nothing about completeness.", "targets": ["AN-30"]},
    {"claim": "A provider that intends to commingle publishes a manifest that lists clean, partitioned sources and simply omits the join step.", "targets": ["AN-30"]},
    {"claim": "This isn't transparency. It's consent-washing with a cryptographic signature.", "targets": ["AN-30"]},
    {"claim": "The logging hook has to be inserted by the auditor, not the audited, and that is source-level access to the pipeline.", "targets": ["AN-30", "AN-26"]}
  ],
  "key_assumptions": [
    {"assumption": "A provider has the technical latitude to publish a manifest whose committed scope excludes the commingling step while still passing as a complete corpus record.", "if_wrong": "If a manifest could be forced to cryptographically cover the join operation itself without the provider controlling scope, the sanitized-manifest hole closes and the proposal verifies the negative from outside — collapsing my source-access requirement."},
    {"assumption": "Auditor-inserted, version-maintained loader-level instrumentation at every frontier provider is what real coverage requires, and Congress has not appropriated a corps to run it.", "if_wrong": "If lightweight, self-maintaining attestation tooling could cover join provenance cheaply, my enforcement-cost objection weakens and the manifest becomes a viable low-cost verification layer."}
  ],
  "disagreement_type": "DEFINITIONAL"
}

