    {"claim": "Route exfiltration discovery into a mandatory public incident registry with the same duty, and the actor whose cost rises is the non-reporter, not the reporter.", "targets": ["AN-43"]},
    {"claim": "Name the enforcement actor with authority to halt a commingled pipeline before a population's data is exfiltrated.", "targets": ["AN-24", "AN-25"]},
    {"claim": "A mandate written against an uninspectable boundary deters the firms that were never going to commingle and licenses the ones that will.", "targets": ["AN-26"]}
